-- A person's grade is dated: each grade they are given applies from a date, the first from the
-- beginning of time (no from-date). On a date the grade in force is the one whose from-date is the
-- latest on or before it. A person has at most one grade per from-date (and one with none).
CREATE TABLE person_grade (
    id        BIGINT     GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_from ON person_grade (person_id, from_key);
INSERT INTO person_grade (person_id, grade, from_date) SELECT id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
-- A person's own terms can be dated: besides the terms they have from the beginning of time (person.terms),
-- each row here records terms (none: no terms of their own) from a date. On a date the terms in force are
-- those whose from-date is the latest on or before it, else those from the beginning of time.
CREATE TABLE person_terms (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    terms     INTEGER,
    from_date DATE   NOT NULL
);
CREATE UNIQUE INDEX person_terms_from ON person_terms (person_id, from_date);
-- A person's past retirements: each one they were unretired from, from the date they were retired from
-- to the day they were unretired. A claim dated after the from and before the to of one is refused.
CREATE TABLE person_retirement (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE NOT NULL,
    to_date   DATE NOT NULL
);
-- Each year end rollover made on the sheet: the fiscal year rolled over, who made it and on which sheet-today,
-- whether it has been undone, the periods it generated, and the period it set opening balances for with the
-- amount it added to each person's, so the last one can be undone.
CREATE TABLE rollover (
    id                BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id          VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    fy                INT           NOT NULL,
    made_by           VARCHAR(200)  NOT NULL,
    made_on           DATE          NOT NULL,
    opening_period_id BIGINT,
    undone            BOOLEAN       DEFAULT FALSE NOT NULL
);
CREATE INDEX rollover_sheet ON rollover (sheet_id, id);
CREATE TABLE rollover_period (
    rollover_id BIGINT NOT NULL REFERENCES rollover (id),
    period_id   BIGINT NOT NULL,
    PRIMARY KEY (rollover_id, period_id)
);
CREATE TABLE rollover_opening (
    rollover_id BIGINT         NOT NULL REFERENCES rollover (id),
    person_id   BIGINT         NOT NULL,
    amount      DECIMAL(15, 2) NOT NULL,
    PRIMARY KEY (rollover_id, person_id)
);
